  if (R.BEAST_HD) Object.keys(R.BEAST_HD).forEach(id => { const d = R.ENEMIES && R.ENEMIES[id]; if (d && !PIX[id] && !/^領主體/.test(d.name || '')) delete R.BEAST_HD[id]; });
  // 攻擊動作的時機：打到人、射出東西
  const mark = e => { if (e && e.m && e.def && !e.dead) e._atkN = (e._atkN || 0) + 1; };
  const hp0 = R.hurtPlayer; if (hp0) R.hurtPlayer = (raw, src, o) => { try { if (src && src.m && src.def) mark(src); } catch (er) { } return hp0(raw, src, o); };
  const fi0 = R.fire; if (fi0) R.fire = o => { try { if (o && o.owner === 'e' && o.src && o.src.def) mark(o.src); } catch (er) { } return fi0(o); };
